#define GFS_PENDING29_PROJECTION_LIBRARY
#include "test_shared_pending29_projection_v1.cpp"
#include "material_shared_oblique_point.h"
namespace os=oblique_slab;namespace op=oblique_point;
namespace {
struct Panel {uint64_t slot,source,target,chart,index,slab,free_child;int32_t eta_index,eta_count;S u0,u1,eta0,eta1;};
struct Axis {uint64_t slot,index,axis,passed;S u,eta,v,s,t,width,J,reference_radius,reference_measure,argument;Q contraction,invariance,forcing,radius,prior,argument_limit;int32_t argument_phase,argument_edge;char reason[192];};
static_assert(sizeof(Panel)==192&&sizeof(Axis)==656,"original candidate/witness ABI");
}
int main(int argc,char**argv){int provided;MPI_Init_thread(&argc,&argv,MPI_THREAD_FUNNELED,&provided);int rank,ranks;MPI_Comm_rank(MPI_COMM_WORLD,&rank);MPI_Comm_size(MPI_COMM_WORLD,&ranks);try{
 need(argc==7&&ranks==1,"packet saved sites weights oldprefix NEWdest");auto begin=std::chrono::steady_clock::now();auto p=curved::read(argv[1]);const auto f=load_saved(std::string(argv[2])+"/shared_state.bin",p);auto before=f.coefficient;auto site=sites(argv[3],argv[4]);std::sort(site.begin(),site.end(),[](const Site&a,const Site&b){return a.id<b.id;});std::string old=argv[5],dest=argv[6];auto panels=read29<Panel>(old+"/candidate_oblique_panels_rank0.bin");auto axes=read29<Axis>(old+"/candidate_axis_proofs_rank0.bin");auto frames=read29<Frame29>(old+"/unchanged_oblique_frames_rank0.bin");auto linear=read29<op::Linear>(old+"/same_chart_linear_coordinates_rank0.bin");auto slabs=read29<os::Slab>(old+"/unchanged_actual_slabs_rank0.bin");std::map<int,sd::Compiled>maps;for(const auto&v:frames)if(!maps.count(v.source))maps.emplace(v.source,sd::compile(f,v.source));std::vector<Axis>out;uint64_t matches=0;std::ofstream csv(dest+"/first_guard_arguments.csv");csv<<"slot_id,panel,axis,reason_match,phase,edge,argument,argument_radius,limit,u,u_radius,eta,eta_radius,reason\n";
 for(const auto&expected:axes)if(!expected.passed){auto pi=std::find_if(panels.begin(),panels.end(),[&](const Panel&b){return b.slot==expected.slot&&b.index==expected.index;});need(pi!=panels.end()&&pi->eta_index==0&&expected.axis==0,"only first failed free-child/eta0 axis, no passing-axis replay");auto fi=std::find_if(frames.begin(),frames.end(),[&](const Frame29&b){return b.slot==expected.slot;});need(fi!=frames.end(),"same saved frame");const auto&frame=*fi;const auto&l=linear[fi-frames.begin()];auto si=std::find_if(slabs.begin(),slabs.end(),[&](const os::Slab&s){return s.slot==expected.slot&&s.index==pi->slab;});need(si!=slabs.end(),"same original actual strip");const auto&m=maps.at(frame.source);std::vector<target::Face>faces;for(const auto&p0:target::planes(site,frame.target))faces.push_back(target::pullback(m,p0));Axis z={};z.slot=expected.slot;z.index=expected.index;z.axis=expected.axis;z.u=expected.u;z.eta=expected.eta;
  try{auto branch=op::prepare(m,faces,frame,l,*si,z.u);auto point=op::point(m,frame,l,z.u,z.eta,branch);z.v=point.v;z.s=point.s;z.t=point.t;z.reference_radius=target::reference_radius(m,frame.original,point.s,point.t,point.value);(void)target::complex_density_bound(p,z.reference_radius);z.passed=1;snprintf(z.reason,sizeof(z.reason),"unexpected_original_failure_pass");}
  catch(const target::GraphFailure&e){snprintf(z.reason,sizeof(z.reason),"%s",e.what());z.contraction=e.contraction;z.invariance=e.invariance;z.forcing=e.forcing;z.radius=e.radius;z.prior=e.prior;}
  catch(const sd::DomainFailure&e){snprintf(z.reason,sizeof(z.reason),"%s",e.what());z.argument=e.argument;z.argument_limit=e.limit;z.argument_phase=e.phase;z.argument_edge=e.edge;}
  catch(const std::exception&e){snprintf(z.reason,sizeof(z.reason),"%s",e.what());}
  bool same=!z.passed&&std::string(z.reason)==expected.reason;matches+=same;out.push_back(z);csv<<z.slot<<','<<z.index<<','<<z.axis<<','<<same<<','<<z.argument_phase<<','<<z.argument_edge;for(Q q:{z.argument.n,z.argument.e,z.argument_limit,z.u.n,z.u.e,z.eta.n,z.eta.e})csv<<','<<qs(q);csv<<','<<z.reason<<'\n';
 }need(out.size()==14&&matches==14,"fourteen original first guard reasons reproduced");csv.close();packet(dest+"/first_guard_arguments_rank0.bin",out,0);need(!memcmp(before.data(),f.coefficient.data(),before.size()*sizeof(STCoefficient)),"read-only witness state/heat");printf("{\"scope\":\"ONLY14saved first-failed axes, reversible phase/argument read-only exception diagnostics; original guard and every arithmetic expression retained\",\"observed_first_failures\":14,\"matched_original_reasons\":14,\"passing_complex_axis_replays\":0,\"new_canonical_root_jobs\":0,\"new_inverse_solves\":0,\"new_physical_quadrature_queries\":0,\"full_quadrature_allowed\":false,\"state_unchanged\":true,\"seconds\":%.17g}\n",std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count());
 }catch(const std::exception&e){fprintf(stderr,"oblique first guard witness FAIL %s\n",e.what());MPI_Abort(MPI_COMM_WORLD,2);}MPI_Finalize();return 0;}
